### ✅ Example 1 — Complete ABC Feature Set

```python name=example1_complete_abc.py
from abc import ABC, abstractmethod
from typing import List, Dict, Any, Optional

# ══════════════════════════════════════════════════
#  COMPLETE ABC — all types of abstract members
# ══════════════════════════════════════════════════

class DataStore(ABC):
    """
    Abstract base class for all data storage backends.
    Defines the CONTRACT every storage implementation must fulfill.
    """

    def __init__(self, name: str, config: Dict = None):
        self.name        = name
        self.config      = config or {}
        self._connected  = False
        self._query_count = 0

    # ─── Abstract Instance Methods ───
    @abstractmethod
    def connect(self) -> bool:
        """Establish connection to the data store"""
        pass

    @abstractmethod
    def disconnect(self) -> None:
        """Close connection gracefully"""
        pass

    @abstractmethod
    def insert(self, collection: str, data: Dict) -> str:
        """Insert a record. Returns the inserted record's ID."""
        pass

    @abstractmethod
    def find(self, collection: str, query: Dict) -> List[Dict]:
        """Find records matching the query."""
        pass

    @abstractmethod
    def update(self, collection: str, query: Dict, new_data: Dict) -> int:
        """Update records. Returns count of updated records."""
        pass

    @abstractmethod
    def delete(self, collection: str, query: Dict) -> int:
        """Delete records. Returns count of deleted records."""
        pass

    # ─── Abstract Class Method ───
    @classmethod
    @abstractmethod
    def from_url(cls, url: str) -> 'DataStore':
        """Alternative constructor: create from connection URL"""
        pass

    # ─── Abstract Static Method ───
    @staticmethod
    @abstractmethod
    def get_driver_name() -> str:
        """Returns the name of the underlying driver/technology"""
        pass

    # ─── Abstract Property ───
    @property
    @abstractmethod
    def is_connected(self) -> bool:
        """Returns True if currently connected"""
        pass

    # ─── Concrete Methods (inherited FREE by all subclasses) ───
    def execute_query(self, collection: str, query: Dict) -> List[Dict]:
        """Template: validates connection then delegates to find()"""
        if not self.is_connected:
            raise ConnectionError(f"Not connected to {self.name}!")
        self._query_count += 1
        return self.find(collection, query)

    def bulk_insert(self, collection: str, records: List[Dict]) -> List[str]:
        """Inserts multiple records — uses single insert() per record"""
        if not self.is_connected:
            raise ConnectionError("Not connected!")
        ids = []
        for record in records:
            ids.append(self.insert(collection, record))
        print(f"  ✅ Bulk inserted {len(ids)} records into '{collection}'")
        return ids

    def health_check(self) -> Dict:
        """Returns health status — works for ANY store type"""
        return {
            "store"       : self.name,
            "connected"   : self.is_connected,
            "query_count" : self._query_count,
            "driver"      : self.get_driver_name(),
        }

    def __enter__(self):
        self.connect()
        return self

    def __exit__(self, *args):
        self.disconnect()

    def __repr__(self):
        return f"{self.__class__.__name__}(name={self.name!r}, connected={self._connected})"

# ─── Concrete Implementation 1: In-Memory Store ───
class InMemoryStore(DataStore):
    """Simple in-memory store — perfect for testing"""

    def __init__(self, name="memory"):
        super().__init__(name)
        self._storage: Dict[str, List[Dict]] = {}
        self._id_counter = 0

    def connect(self) -> bool:
        self._connected = True
        print(f"  ✅ InMemory: Connected")
        return True

    def disconnect(self) -> None:
        self._connected = False
        print(f"  ❌ InMemory: Disconnected")

    def insert(self, collection: str, data: Dict) -> str:
        self._id_counter += 1
        record = {"_id": str(self._id_counter), **data}
        self._storage.setdefault(collection, []).append(record)
        return record["_id"]

    def find(self, collection: str, query: Dict) -> List[Dict]:
        records = self._storage.get(collection, [])
        if not query:
            return records.copy()
        return [
            r for r in records
            if all(r.get(k) == v for k, v in query.items())
        ]

    def update(self, collection: str, query: Dict, new_data: Dict) -> int:
        count = 0
        for r in self._storage.get(collection, []):
            if all(r.get(k) == v for k, v in query.items()):
                r.update(new_data)
                count += 1
        return count

    def delete(self, collection: str, query: Dict) -> int:
        original = self._storage.get(collection, [])
        filtered = [r for r in original
                    if not all(r.get(k) == v for k, v in query.items())]
        deleted  = len(original) - len(filtered)
        self._storage[collection] = filtered
        return deleted

    @classmethod
    def from_url(cls, url: str) -> 'InMemoryStore':
        return cls(name=url.split("//")[-1])

    @staticmethod
    def get_driver_name() -> str:
        return "Python dict (in-memory)"

    @property
    def is_connected(self) -> bool:
        return self._connected

# ─── Concrete Implementation 2: Simulated PostgreSQL ───
class PostgreSQLStore(DataStore):

    def connect(self) -> bool:
        host = self.config.get('host', 'localhost')
        port = self.config.get('port', 5432)
        print(f"  🐘 PostgreSQL: Connecting to {host}:{port}/{self.name}...")
        self._connected = True
        return True

    def disconnect(self) -> None:
        print(f"  🐘 PostgreSQL: Connection closed")
        self._connected = False

    def insert(self, collection: str, data: Dict) -> str:
        print(f"  🐘 INSERT INTO {collection} VALUES {data} RETURNING id")
        return f"pg_{len(data)}"

    def find(self, collection: str, query: Dict) -> List[Dict]:
        conditions = " AND ".join(f"{k}='{v}'" for k, v in query.items())
        where      = f" WHERE {conditions}" if conditions else ""
        print(f"  🐘 SELECT * FROM {collection}{where}")
        return [{"mock": "data"}]

    def update(self, collection: str, query: Dict, new_data: Dict) -> int:
        print(f"  🐘 UPDATE {collection} SET {new_data} WHERE {query}")
        return 1

    def delete(self, collection: str, query: Dict) -> int:
        print(f"  🐘 DELETE FROM {collection} WHERE {query}")
        return 1

    @classmethod
    def from_url(cls, url: str) -> 'PostgreSQLStore':
        # Parse: postgresql://user:pass@host:port/dbname
        dbname = url.split("/")[-1]
        host   = url.split("@")[-1].split("/")[0].split(":")[0]
        return cls(name=dbname, config={"host": host})

    @staticmethod
    def get_driver_name() -> str:
        return "PostgreSQL 15 via psycopg2"

    @property
    def is_connected(self) -> bool:
        return self._connected

# ─── Testing ───
print("=== Cannot instantiate ABC ===")
try:
    ds = DataStore("test")
except TypeError as e:
    print(f"❌ {e}")

print("\n=== InMemoryStore ===")
with InMemoryStore() as store:
    store.bulk_insert("users", [
        {"name": "Alice", "role": "admin",  "age": 28},
        {"name": "Bob",   "role": "user",   "age": 32},
        {"name": "Carol", "role": "user",   "age": 25},
    ])
    users   = store.execute_query("users", {"role": "user"})
    print(f"  Users with role='user': {[u['name'] for u in users]}")
    updated = store.update("users", {"name": "Bob"}, {"role": "admin"})
    print(f"  Updated: {updated} record(s)")
    deleted = store.delete("users", {"name": "Carol"})
    print(f"  Deleted: {deleted} record(s)")
    print(f"  Health: {store.health_check()}")

print("\n=== from_url constructor ===")
pg_store = PostgreSQLStore.from_url("postgresql://admin:pass@prod-server:5432/appdb")
print(pg_store)

print("\n=== isinstance/issubclass ===")
mem = InMemoryStore()
print(f"isinstance(mem, DataStore)    : {isinstance(mem, DataStore)}")  # True
print(f"issubclass(PostgreSQLStore, DataStore): {issubclass(PostgreSQLStore, DataStore)}")
```

### ✅ Example 2 — Virtual Subclasses & `__subclasshook__`

```python name=example2_virtual_subclasses.py
from abc import ABC, abstractmethod

# ══════════════════════════════════════════════════
#  VIRTUAL SUBCLASSES — register() and __subclasshook__
#  Make classes behave as if they're subclasses
#  WITHOUT actually inheriting!
# ══════════════════════════════════════════════════

class Drawable(ABC):
    """
    Abstract interface for anything that can be drawn.
    Using __subclasshook__ to define duck-typing ABC.
    """

    @abstractmethod
    def draw(self):
        pass

    @abstractmethod
    def get_color(self):
        pass

    @classmethod
    def __subclasshook__(cls, C):
        """
        Custom isinstance() check.
        If a class has BOTH draw() and get_color() methods,
        treat it as a Drawable — even without explicit inheritance!
        """
        if cls is Drawable:
            # Check if the class has draw and get_color methods
            has_draw      = any("draw"      in B.__dict__ for B in C.__mro__)
            has_get_color = any("get_color" in B.__dict__ for B in C.__mro__)
            if has_draw and has_get_color:
                return True   # treat as Drawable!
        return NotImplemented  # use normal subclass check

class Serializable(ABC):
    """
    Abstract interface for serializable objects.
    Demonstrates register() for virtual subclasses.
    """

    @abstractmethod
    def serialize(self) -> dict:
        pass

    @classmethod
    @abstractmethod
    def deserialize(cls, data: dict):
        pass

# ─── Existing class WITHOUT inheriting from Drawable ───
class LegacyShape:
    """
    Old class from a legacy library — can't modify it.
    But it HAS draw() and get_color() methods.
    """
    def draw(self):
        print("Legacy shape drawing...")

    def get_color(self):
        return "gray"

# ─── Another class using register() ───
class ThirdPartyCircle:
    """Another third-party class — register it as Serializable"""
    def __init__(self, radius):
        self.radius = radius

    def serialize(self) -> dict:
        return {"type": "circle", "radius": self.radius}

    @classmethod
    def deserialize(cls, data: dict):
        return cls(data["radius"])

# Register ThirdPartyCircle as Serializable WITHOUT inheritance
Serializable.register(ThirdPartyCircle)

# ─── Testing ───
legacy = LegacyShape()
third  = ThirdPartyCircle(5)

print("=== __subclasshook__ ===")
print(f"isinstance(legacy, Drawable): {isinstance(legacy, Drawable)}")  # True! (duck typing)
print(f"LegacyShape in Drawable's subclasses? "
      f"{issubclass(LegacyShape, Drawable)}")  # True!

print("\n=== register() ===")
print(f"isinstance(third, Serializable)       : {isinstance(third, Serializable)}")
print(f"issubclass(ThirdPartyCircle, Serializable): {issubclass(ThirdPartyCircle, Serializable)}")

# But ThirdPartyCircle doesn't ACTUALLY inherit from Serializable
print(f"Serializable in ThirdPartyCircle.__mro__: "
      f"{Serializable in ThirdPartyCircle.__mro__}")  # False!

# Check all registered subclasses
print(f"\nSerializable subclasses: {Serializable.__subclasses__()}")

# ─── Practical use: collections.abc ───
from collections.abc import Sized, Iterable, Mapping

class CustomCollection:
    """
    Custom collection that Python's built-in ABCs recognize
    through __subclasshook__ (Sized requires __len__, etc.)
    """
    def __init__(self, *items):
        self._items = list(items)

    def __len__(self):
        return len(self._items)

    def __iter__(self):
        return iter(self._items)

    def __getitem__(self, key):
        return self._items[key]

coll = CustomCollection(1, 2, 3, 4, 5)

print("\n=== Collections ABC Recognition ===")
print(f"isinstance(coll, Sized)    : {isinstance(coll, Sized)}")    # True!
print(f"isinstance(coll, Iterable) : {isinstance(coll, Iterable)}") # True!
print(f"isinstance([], Sized)      : {isinstance([], Sized)}")       # True
print(f"isinstance({{}}, Mapping)    : {isinstance({}, Mapping)}")    # True

# Works in type-checking functions
def process_sized(obj: Sized):
    print(f"Processing {len(obj)}-item collection")

process_sized(coll)
process_sized([1, 2, 3])
process_sized("hello")
```

### ✅ Example 3 — Interface Segregation with Multiple ABCs

```python name=example3_interface_segregation.py
from abc import ABC, abstractmethod
from typing import List, Optional

# ══════════════════════════════════════════════════
#  INTERFACE SEGREGATION PRINCIPLE (ISP)
#  "Clients should not be forced to depend on
#   interfaces they don't use"
#
#  Instead of ONE big ABC → multiple SMALL ABCs
# ══════════════════════════════════════════════════

# ─── Small, focused interfaces ───
class Readable(ABC):
    @abstractmethod
    def read(self) -> str: pass

class Writable(ABC):
    @abstractmethod
    def write(self, data: str) -> bool: pass

class Seekable(ABC):
    @abstractmethod
    def seek(self, position: int) -> None: pass

    @abstractmethod
    def tell(self) -> int: pass

class Closeable(ABC):
    @abstractmethod
    def close(self) -> None: pass

    @abstractmethod
    def is_closed(self) -> bool: pass

class Flushable(ABC):
    @abstractmethod
    def flush(self) -> None: pass

# ─── Combine as needed ───
class ReadOnlyFile(Readable, Seekable, Closeable):
    """Read-only file — can read and seek, not write"""

    def __init__(self, filepath):
        self.filepath = filepath
        self._content = ""
        self._pos     = 0
        self._closed  = False
        # Simulate reading
        self._content = f"[Content of {filepath}]\nLine 1\nLine 2\nLine 3"

    def read(self) -> str:
        if self._closed: raise IOError("File is closed!")
        data      = self._content[self._pos:]
        self._pos = len(self._content)
        return data

    def seek(self, position: int) -> None:
        if self._closed: raise IOError("File is closed!")
        self._pos = max(0, min(position, len(self._content)))

    def tell(self) -> int:
        return self._pos

    def close(self) -> None:
        self._closed = True
        print(f"  📁 {self.filepath} closed (read-only)")

    def is_closed(self) -> bool:
        return self._closed

class ReadWriteFile(Readable, Writable, Seekable, Closeable, Flushable):
    """Full read-write file — implements ALL interfaces"""

    def __init__(self, filepath):
        self.filepath  = filepath
        self._content  = ""
        self._buffer   = ""
        self._pos      = 0
        self._closed   = False

    def read(self) -> str:
        if self._closed: raise IOError("File is closed!")
        return self._content[self._pos:]

    def write(self, data: str) -> bool:
        if self._closed: raise IOError("File is closed!")
        self._buffer += data
        print(f"  📝 Buffered: {data!r}")
        return True

    def flush(self) -> None:
        self._content += self._buffer
        print(f"  💾 Flushed {len(self._buffer)} bytes to {self.filepath}")
        self._buffer   = ""

    def seek(self, position: int) -> None:
        self._pos = position

    def tell(self) -> int:
        return self._pos

    def close(self) -> None:
        if self._buffer: self.flush()
        self._closed = True
        print(f"  📁 {self.filepath} closed (read-write)")

    def is_closed(self) -> bool:
        return self._closed

class NetworkStream(Readable, Writable, Closeable):
    """Network stream — no seek (network isn't seekable!)"""

    def __init__(self, host, port):
        self.host    = host
        self.port    = port
        self._closed = False

    def read(self) -> str:
        return f"[Data from {self.host}:{self.port}]"

    def write(self, data: str) -> bool:
        print(f"  📡 Sent to {self.host}:{self.port}: {data!r}")
        return True

    def close(self) -> None:
        self._closed = True
        print(f"  🔌 Connection to {self.host}:{self.port} closed")

    def is_closed(self) -> bool:
        return self._closed

# ─── Functions that accept specific interfaces ───
def copy_data(source: Readable, dest: Writable) -> None:
    """Works with ANY Readable source → ANY Writable dest"""
    data = source.read()
    dest.write(data)
    print(f"  ✅ Copied {len(data)} bytes")

def backup(source: Readable, dest: Writable) -> None:
    """Backup: read from source, write to dest"""
    copy_data(source, dest)
    if isinstance(dest, Flushable):
        dest.flush()
    if isinstance(source, Closeable):
        source.close()
    if isinstance(dest, Closeable):
        dest.close()

# ─── Testing ───
print("=== Interface checks ===")
rw_file = ReadWriteFile("output.txt")
ro_file = ReadOnlyFile("input.txt")
stream  = NetworkStream("api.example.com", 443)

print(f"rw_file is Readable  : {isinstance(rw_file, Readable)}")
print(f"rw_file is Writable  : {isinstance(rw_file, Writable)}")
print(f"rw_file is Seekable  : {isinstance(rw_file, Seekable)}")
print(f"ro_file is Writable  : {isinstance(ro_file, Writable)}")  # False!
print(f"stream  is Seekable  : {isinstance(stream, Seekable)}")   # False!

print("\n=== copy_data: file → file ===")
copy_data(ro_file, rw_file)

print("\n=== copy_data: file → network ===")
ro_file2 = ReadOnlyFile("log.txt")
copy_data(ro_file2, stream)

print("\n=== backup (full pipeline) ===")
src  = ReadOnlyFile("source.dat")
dest = ReadWriteFile("backup.dat")
backup(src, dest)

# Cannot pass wrong type
def requires_seekable(obj: Seekable):
    print(f"  Current position: {obj.tell()}")

print("\n=== Type safety with ISP ===")
requires_seekable(rw_file)   # ✅
try:
    requires_seekable(stream)    # stream is NOT Seekable
    stream.seek(0)               # AttributeError — doesn't have seek!
except AttributeError as e:
    print(f"  ❌ {e}")
```

### ✅ Example 4 — Template Method Pattern with ABC

```python name=example4_template_method.py
from abc import ABC, abstractmethod
from datetime import datetime
import time

# ══════════════════════════════════════════════════
#  TEMPLATE METHOD PATTERN — ABC defines the skeleton
#  Subclasses fill in the specific steps
# ══════════════════════════════════════════════════

class ReportGenerator(ABC):
    """
    Template Method Pattern:
    The abstract class defines the STRUCTURE (generate()),
    subclasses implement the STEPS.
    """

    def generate(self, output_format="console") -> str:
        """
        TEMPLATE METHOD — fixed algorithm skeleton.
        Steps are called in order. Each step may be overridable.
        """
        print(f"\n{'='*60}")
        print(f"  Generating: {self.get_report_title()}")
        print(f"  Format    : {output_format}")
        print(f"{'='*60}")

        # Fixed steps — same order for ALL reports
        self._start_timer()
        raw_data     = self.fetch_data()             # abstract
        clean_data   = self.clean_data(raw_data)     # hook (overridable)
        validated    = self.validate_data(clean_data)# abstract
        processed    = self.process_data(validated)  # abstract
        report_str   = self.format_report(processed, # abstract
                                          output_format)
        self._stop_timer()

        self.on_report_complete(report_str)          # hook

        return report_str

    # ─── Abstract steps: MUST be implemented ───
    @abstractmethod
    def get_report_title(self) -> str:
        pass

    @abstractmethod
    def fetch_data(self) -> list:
        pass

    @abstractmethod
    def validate_data(self, data: list) -> list:
        pass

    @abstractmethod
    def process_data(self, data: list) -> dict:
        pass

    @abstractmethod
    def format_report(self, processed: dict, fmt: str) -> str:
        pass

    # ─── Hook methods: CAN be overridden (have defaults) ───
    def clean_data(self, data: list) -> list:
        """Default: remove None values. Override for custom cleaning."""
        return [d for d in data if d is not None]

    def on_report_complete(self, report: str) -> None:
        """Hook: called after report generated. Override to email/save/etc."""
        print(f"\n  ✅ Report complete ({self._elapsed:.3f}s)")

    # ─── Private template helpers ───
    def _start_timer(self):
        self._start = time.perf_counter()

    def _stop_timer(self):
        self._elapsed = time.perf_counter() - self._start

class SalesReport(ReportGenerator):
    """Monthly sales report"""

    def __init__(self, month: str, year: int):
        self.month = month
        self.year  = year

    def get_report_title(self) -> str:
        return f"Sales Report — {self.month} {self.year}"

    def fetch_data(self) -> list:
        print(f"  📊 Fetching sales data from DB...")
        # Simulated data
        return [
            {"product": "Laptop",   "units": 45, "revenue": 3375000},
            {"product": "Phone",    "units": 120,"revenue": 1800000},
            {"product": "Tablet",   "units": 30, "revenue": 600000},
            None,   # dirty data!
            {"product": "Earbuds",  "units": 200,"revenue": 500000},
        ]

    def validate_data(self, data: list) -> list:
        valid = []
        for record in data:
            if record.get("units", 0) <= 0:
                print(f"  ⚠️  Skipping invalid record: {record}")
                continue
            valid.append(record)
        return valid

    def process_data(self, data: list) -> dict:
        return {
            "total_revenue"  : sum(d["revenue"] for d in data),
            "total_units"    : sum(d["units"] for d in data),
            "best_product"   : max(data, key=lambda x: x["revenue"])["product"],
            "product_count"  : len(data),
            "records"        : data
        }

    def format_report(self, processed: dict, fmt: str) -> str:
        lines = [
            f"\n  📊 {self.get_report_title()}",
            f"  {'─'*40}",
            f"  Total Revenue : ₹{processed['total_revenue']:>15,.2f}",
            f"  Total Units   : {processed['total_units']:>15,}",
            f"  Best Product  : {processed['best_product']:>15}",
            f"  Products      : {processed['product_count']:>15}",
            f"  {'─'*40}",
        ]
        for record in processed["records"]:
            lines.append(
                f"  {record['product']:<12} "
                f"Units: {record['units']:>4} | "
                f"₹{record['revenue']:>12,.0f}"
            )
        return "\n".join(lines)

    def on_report_complete(self, report: str) -> None:
        super().on_report_complete(report)
        print(f"  📧 Emailing to management team...")

class InventoryReport(ReportGenerator):
    """Current inventory status report"""

    def get_report_title(self) -> str:
        return f"Inventory Status — {datetime.now().strftime('%Y-%m-%d')}"

    def fetch_data(self) -> list:
        print(f"  📦 Fetching inventory from warehouse system...")
        return [
            {"item": "Laptop",  "stock": 12,  "reorder": 20, "value": 900000},
            {"item": "Phone",   "stock": 5,   "reorder": 30, "value": 75000},
            {"item": "Tablet",  "stock": 0,   "reorder": 15, "value": 0},
            {"item": "Monitor", "stock": 25,  "reorder": 10, "value": 750000},
            {"item": "Keyboard","stock": 3,   "reorder": 10, "value": 9000},
        ]

    def clean_data(self, data: list) -> list:
        """Override: also normalize item names to uppercase"""
        cleaned = super().clean_data(data)   # call parent's clean first
        for item in cleaned:
            item["item"] = item["item"].upper()
        return cleaned

    def validate_data(self, data: list) -> list:
        return [d for d in data if "item" in d and "stock" in d]

    def process_data(self, data: list) -> dict:
        critical = [d for d in data if d["stock"] == 0]
        low      = [d for d in data if 0 < d["stock"] <= d["reorder"]]
        ok       = [d for d in data if d["stock"] > d["reorder"]]
        return {
            "critical"     : critical,
            "low_stock"    : low,
            "ok"           : ok,
            "total_value"  : sum(d["value"] for d in data),
            "records"      : data
        }

    def format_report(self, processed: dict, fmt: str) -> str:
        lines = [
            f"\n  📦 {self.get_report_title()}",
            f"  Total Inventory Value: ₹{processed['total_value']:,.2f}",
            f"\n  ❌ CRITICAL (Out of Stock): {len(processed['critical'])} items",
        ]
        for i in processed["critical"]:
            lines.append(f"    → {i['item']}")
        lines.append(f"\n  ⚠️  LOW STOCK: {len(processed['low_stock'])} items")
        for i in processed["low_stock"]:
            lines.append(f"    → {i['item']} ({i['stock']} left, reorder at {i['reorder']})")
        lines.append(f"\n  ✅ OK: {len(processed['ok'])} items")
        return "\n".join(lines)

