### ✅ Example 5 — ABCMeta & Advanced ABC Patterns

```python name=example5_abcmeta_advanced.py
from abc import ABC, abstractmethod, ABCMeta
import inspect

# ══════════════════════════════════════════════════
#  ABCMETA DIRECTLY + ADVANCED PATTERNS
# ══════════════════════════════════════════════════

# ─── ABCMeta directly (older style, same effect) ───
class Plugin(metaclass=ABCMeta):
    """Using ABCMeta directly instead of inheriting ABC"""

    @abstractmethod
    def execute(self, context: dict) -> dict: pass

    @abstractmethod
    def get_name(self) -> str: pass

    @abstractmethod
    def get_version(self) -> str: pass

    def __repr__(self):
        return f"<Plugin: {self.get_name()} v{self.get_version()}>"

# ─── Abstract class with abstract CLASS variable ───
class BaseConfig(ABC):
    """
    Base configuration class.
    Subclasses MUST define the CONFIG_SCHEMA class variable.
    We enforce this via __init_subclass__.
    """

    # Cannot make a class variable abstract directly,
    # but we can enforce it via __init_subclass__
    CONFIG_SCHEMA: dict = None   # must be overridden!

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        if not inspect.isabstract(cls):
            if cls.CONFIG_SCHEMA is None:
                raise TypeError(
                    f"❌ {cls.__name__} must define CONFIG_SCHEMA class variable!"
                )

    @abstractmethod
    def validate(self) -> bool: pass

    @abstractmethod
    def load(self, source: str) -> None: pass

    def get_schema(self) -> dict:
        return self.CONFIG_SCHEMA

# ─── Working concrete implementations ───
class DatabaseConfig(BaseConfig):
    CONFIG_SCHEMA = {
        "host"    : str,
        "port"    : int,
        "name"    : str,
        "user"    : str,
        "password": str,
    }

    def __init__(self):
        self._settings = {}

    def validate(self) -> bool:
        return all(k in self._settings for k in self.CONFIG_SCHEMA)

    def load(self, source: str) -> None:
        # In real code: load from file/env
        self._settings = {
            "host": "localhost", "port": 5432,
            "name": "appdb",    "user": "admin", "password": "secret"
        }
        print(f"  ✅ Config loaded from {source}")

# ─── Forgot CONFIG_SCHEMA — should raise error ───
try:
    class BadConfig(BaseConfig):
        # CONFIG_SCHEMA = {...}  ← forgot!
        def validate(self): return True
        def load(self, s): pass
except TypeError as e:
    print(f"Enforcement works: {e}")

# ─── Abstract class introspection ───
class AbstractInspector:
    """Utility to inspect abstract classes"""

    @staticmethod
    def get_abstract_methods(cls) -> list:
        return list(getattr(cls, '__abstractmethods__', set()))

    @staticmethod
    def get_concrete_methods(cls) -> list:
        abstract = set(getattr(cls, '__abstractmethods__', set()))
        return [
            name for name, member in inspect.getmembers(cls, predicate=inspect.isfunction)
            if name not in abstract and not name.startswith('__')
        ]

    @staticmethod
    def is_fully_implemented(cls) -> bool:
        return len(getattr(cls, '__abstractmethods__', set())) == 0

    @staticmethod
    def implementation_report(cls) -> str:
        abstract  = AbstractInspector.get_abstract_methods(cls)
        concrete  = AbstractInspector.get_concrete_methods(cls)
        complete  = AbstractInspector.is_fully_implemented(cls)
        lines = [
            f"\n  📋 Implementation Report: {cls.__name__}",
            f"  Status     : {'✅ Complete' if complete else '❌ Incomplete'}",
            f"  Abstract   : {abstract or 'None'}",
            f"  Concrete   : {concrete}",
        ]
        return "\n".join(lines)

# ─── Partial implementation (still abstract) ───
class PartialStore(Plugin):
    """Implements get_name but NOT execute or get_version"""
    def get_name(self) -> str:
        return "PartialStore"
    # Missing: execute() and get_version()

# ─── Full implementation ───
class LoggingPlugin(Plugin):
    def execute(self, context: dict) -> dict:
        print(f"  📋 LoggingPlugin executing with {len(context)} context keys")
        context["logged"] = True
        return context

    def get_name(self) -> str:
        return "LoggingPlugin"

    def get_version(self) -> str:
        return "2.1.0"

class CachingPlugin(Plugin):
    def __init__(self):
        self._cache = {}

    def execute(self, context: dict) -> dict:
        key = str(sorted(context.items()))
        if key in self._cache:
            print(f"  ⚡ Cache hit!")
            return self._cache[key]
        context["cached"] = False
        self._cache[key]  = context
        return context

    def get_name(self) -> str:
        return "CachingPlugin"

    def get_version(self) -> str:
        return "1.0.3"

# ─── Plugin Manager using ABC type ───
class PluginManager:
    def __init__(self):
        self._plugins: list[Plugin] = []

    def register(self, plugin: Plugin):
        if not isinstance(plugin, Plugin):
            raise TypeError(f"❌ {type(plugin).__name__} is not a Plugin!")
        self._plugins.append(plugin)
        print(f"  ✅ Registered: {plugin}")

    def execute_all(self, context: dict) -> dict:
        for plugin in self._plugins:
            context = plugin.execute(context)
        return context

